import{_ as e,o as a,c as d,ae as o}from"./chunks/framework.DQC_QtFV.js";const _=JSON.parse('{"title":"控制台概览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/console/index.md","filePath":"guide/console/index.md","lastUpdated":1793162416000}'),r={name:"guide/console/index.md"};function n(i,t,l,h,c,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="控制台概览" tabindex="-1">控制台概览 <a class="header-anchor" href="#控制台概览" aria-label="Permalink to &quot;控制台概览&quot;">​</a></h1><p>控制台是这台机器的面板：<a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a>，用 <code>CONSOLE_PASSWORD</code> 登录， 一个会话 cookie，登录前什么都用不了。它是唯一打算发布的服务，也只有它需要被发布。</p><p>左侧导航分四组，每组一个主题，一个功能的所有开关和数字都在它自己那一页：</p><table tabindex="0"><thead><tr><th>分组</th><th>页面</th></tr></thead><tbody><tr><td>运行</td><td>概览、QQ</td></tr><tr><td>机器人</td><td>会话、人设、记忆、表情包、定时</td></tr><tr><td>设置</td><td>模型、安全、工作区、高级</td></tr><tr><td>—</td><td>日志、退出登录</td></tr></tbody></table><p>状态块常驻在左侧：QQ 登录态、数据库密钥、机器人和 Jev 的灯、窗口 token 水位、 暂停 / 恢复。</p><h2 id="概览-先看这一页" tabindex="-1">概览：先看这一页 <a class="header-anchor" href="#概览-先看这一页" aria-label="Permalink to &quot;概览：先看这一页&quot;">​</a></h2><p>待处理 只列问题——QQ 没登录、密钥不是 ok、没有主模型、Jev 缺失或不可达、 允许列表是空的、被允许的会话落在读取范围外、机器人被暂停、有技能源更新失败—— 每项后面跟着一个能修它的按钮，处理好一项它就消失。没有问题时刻意是空的。</p><p>下面三张摘要卡（QQ、机器人、会话）和 最近动态（最近五条轮次、发送和插话记录）。</p><h2 id="qq-连接与实时画面" tabindex="-1">QQ：连接与实时画面 <a class="header-anchor" href="#qq-连接与实时画面" aria-label="Permalink to &quot;QQ：连接与实时画面&quot;">​</a></h2><p>连接 卡片一行一个状态：客户端在不在跑、登录状态、版本、数据库密钥 （ok / missing / invalid，不是 ok 时给出重新提取的步骤）、最近同步时间、镜像延迟。 下面的 登录 按钮是手动重试——重启后驱动程序会自己点一次。</p><p>实时画面 就是客户端自己的 framebuffer，经控制台代理转出来，VNC 端口不对外暴露。 扫码在这里完成；画面按 1:1 像素画在会滚动的框里，适应窗口 切换到整体缩放。 画面大小由 <code>SCREEN_W</code> x <code>SCREEN_H</code> 决定（见 <a href="./../env.html">环境变量</a>）。</p><h2 id="页面读法" tabindex="-1">页面读法 <a class="header-anchor" href="#页面读法" aria-label="Permalink to &quot;页面读法&quot;">​</a></h2><p>面板刻意做得简单：一个次级账号上的个人助理，没有用户、角色和多账号切换。 每一页都把当前值显示成一行，改它的表单收在弹出层、抽屉或模态里，不摆一长条平铺的表单。 原始 id、ref 和次要字段都在弹出层或&quot;详情&quot;里，一键复制。</p>',13)])])}const f=e(r,[["render",n]]);export{_ as __pageData,f as default};
